public static class OfficeConfiguration {
    public static readonly string[] Apps={"Word","Excel","PowerPoint","Outlook","OneNote","Access","OneDrive"};
    public static XDocument Build(OfficeEdition edition,string architecture,string language,string version,IEnumerable<string> apps,string source,bool accept){
        if(edition==null||!OfficeEdition.All().Any(x=>x.Product==edition.Product&&x.Channel==edition.Channel))throw new ArgumentException("Invalid Office edition");if(architecture!="32"&&architecture!="64")throw new ArgumentException("Invalid architecture");if(!new[]{"MatchOS","pt-br","pt-pt","en-us","es-es"}.Contains(language))throw new ArgumentException("Invalid language");var chosen=new HashSet<string>(apps);if(chosen.Count==0||chosen.All(x=>x=="OneDrive")||chosen.Any(x=>!Apps.Contains(x))||!edition.Access&&chosen.Contains("Access")||!edition.Outlook&&chosen.Contains("Outlook"))throw new ArgumentException(L.T("Selecione pelo menos um aplicativo Office disponível na edição.","Select at least one Office app available in this edition."));if(!String.IsNullOrWhiteSpace(version)&&!Regex.IsMatch(version,"^16\\.0\\.[0-9]{4,6}\\.[0-9]{4,6}$"))throw new ArgumentException("Invalid Office build");
        XElement product=new XElement("Product",new XAttribute("ID",edition.Product));XElement lang=new XElement("Language",new XAttribute("ID",language));if(language=="MatchOS")lang.SetAttributeValue("Fallback","en-us");product.Add(lang);foreach(string app in Apps.Where(x=>!chosen.Contains(x)))product.Add(new XElement("ExcludeApp",new XAttribute("ID",app)));foreach(string extra in new[]{"Groove","Lync","Publisher","Teams","OutlookForWindows"})product.Add(new XElement("ExcludeApp",new XAttribute("ID",extra)));
        XElement add=new XElement("Add",new XAttribute("OfficeClientEdition",architecture),new XAttribute("Channel",edition.Channel),new XAttribute("AllowCdnFallback","TRUE"),product);if(!String.IsNullOrWhiteSpace(source))add.SetAttributeValue("SourcePath",Args.LocalPath(source));if(!String.IsNullOrWhiteSpace(version))add.SetAttributeValue("Version",version);return new XDocument(new XElement("Configuration",add,new XElement("Display",new XAttribute("Level","Full"),new XAttribute("AcceptEULA",accept?"TRUE":"FALSE")),new XElement("Property",new XAttribute("Name","FORCEAPPSHUTDOWN"),new XAttribute("Value","FALSE")),new XElement("Updates",new XAttribute("Enabled","TRUE"))));
    }
    public static string VerifyTool(string file){string path=Args.LocalPath(file);if(!File.Exists(path)||!Path.GetExtension(path).Equals(".exe",StringComparison.OrdinalIgnoreCase))throw new FileNotFoundException("Select extracted Office Deployment Tool setup.exe",path);var info=FileVersionInfo.GetVersionInfo(path);if(((info.FileDescription??"")+" "+(info.ProductName??"")).IndexOf("Office",StringComparison.OrdinalIgnoreCase)<0)throw new InvalidDataException("Selected executable does not identify itself as an Office tool");var r=Runner.PS("$s=Get-AuthenticodeSignature -LiteralPath "+Runner.QuotePS(path)+"; if ($s.Status -ne 'Valid' -or $s.SignerCertificate.Subject -notmatch 'O=Microsoft Corporation') { throw 'A valid Microsoft signature is required' }; Write-Output 'Microsoft signature verified'",30000);if(r.Code!=0)throw new InvalidDataException(r.Output);return path;}
}
